	createvisualtask AnimTask_ShakeMon2, 2, ANIM_ATK_PARTNER, 1, 0, 6, 1
	createvisualtask SoundTask_WaitForCry, 2, 1, 0, 6, 1
	delay 20
	jumpifdoublebattle Boomburst_Doubles
