	waitbgfadein
	monbg ANIM_ATK_PARTNER
	playsewithpan SE_M_MEGA_KICK, SOUND_PAN_ATTACKER
	call ContinentalCrushStockpileRocks
	playsewithpan SE_M_MEGA_KICK, SOUND_PAN_ATTACKER
	call ContinentalCrushStockpileRocks
	waitforvisualfinish
	clearmonbg ANIM_ATK_PARTNER
	call UnsetBackground
	end

MeteorBeamBlast:
