	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	call MeteorBeamRockLaunch
	waitforvisualfinish
	clearmonbg ANIM_TARGET
