	createvisualtask AnimTask_ShakeMon, 2, ANIM_TARGET, 0, 4, 10, 1
	delay 20
	createvisualtask AnimTask_TwinkleTackleLaunch, 2, 50
	delay 50
	playsewithpan SE_M_DETECT, SOUND_PAN_TARGET
