MakingItRainContinue:
	waitbgfadeout
	shake_mon_or_platform velocity=7, shake_timer=1, shake_duration=11, type=SHAKE_BG_Y
	loopsewithpan SE_M_PAY_DAY, SOUND_PAN_TARGET, 8, 15
