SetHighSpeedBg:
	createvisualtask AnimTask_GetAttackerSide, 2
	jumprettrue SetHighSpeedBgPlayer
	fadetobg BG_HIGHSPEED_OPPONENT
	goto SetHighSpeedBgFade
SetHighSpeedBgPlayer:
	fadetobg BG_HIGHSPEED_PLAYER
SetHighSpeedBgFade:
	waitbgfadeout
	createvisualtask AnimTask_StartSlidingBg, 5, -2304, 0, 1, -1
	waitbgfadein
	return

gBattleAnimMove_MachPunch::
	monbg ANIM_ATK_PARTNER
	call SetHighSpeedBg
	delay 0
	setalpha 9, 8
	createvisualtask AnimTask_AttackerPunchWithTrace, 2, RGB(8, 9, 28), 10
	playsewithpan SE_M_JUMP_KICK, SOUND_PAN_ATTACKER
	delay 6
	create_basic_hitsplat_sprite ANIM_TARGET, 3, x=0, y=0, relative_to=ANIM_TARGET, animation=1
	create_fist_sprite ANIM_TARGET, 4, x=0, y=0, duration=8, initPosition=1
	playsewithpan SE_M_COMET_PUNCH, SOUND_PAN_TARGET
	createvisualtask AnimTask_ShakeMon, 2, ANIM_TARGET, 3, 0, 6, 1
	waitforvisualfinish
	clearmonbg ANIM_ATK_PARTNER
	blendoff
	call UnsetBackground
	end

