	createvisualtask AnimTask_BlendBattleAnimPal, 10, F_PAL_DEF_PARTNER, 2, 11, 0, RGB(21, 2, 0)
	waitbgfadein
	clearmonbg ANIM_DEF_PARTNER
	blendoff
	end

