	delay 1
	waitforvisualfinish
	fadetobg BG_SWAMP
	createvisualtask AnimTask_CreateRaindrops, 2, 0, 3, 60
	createvisualtask AnimTask_CreateRaindrops, 2, 0, 3, 60
