	waitforvisualfinish
	delay 10
	createsprite gCorkscrewCrashRightDownSpriteTemplate, ANIM_ATTACKER, 50, -16, 56, 256, 56, 21
	waitforvisualfinish
	visible ANIM_TARGET
	delay 5
