	delay 4
	createsprite gSoulStealBlueStarSpriteTemplate, ANIM_TARGET, 4, 0, 1, 2, 0, 0, 24
	playsewithpan SE_M_JUMP_KICK, SOUND_PAN_TARGET
	createsprite gSoulStealBlueFistSpriteTemplate, ANIM_TARGET, 2, -64, 14, 0, 0, 10, 1, 0, 1
	delay 4
